import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';

// Store1 Components
import Store1StockOperations from './components/Store1/StockOperations';
import Store1SalesOperations from './components/Store1/SalesOperations';
import Store1ReturnOperations from './components/Store1/ReturnOperations';

// Store2 Components
import Store2StockOperations from './components/Store2/StockOperations';
import Store2SalesOperations from './components/Store2/SalesOperations';
import Store2ReturnOperations from './components/Store2/ReturnOperations';

// Store3 Components
import Store3StockOperations from './components/Store3/StockOperations';
import Store3SalesOperations from './components/Store3/SalesOperations';
import Store3ReturnOperations from './components/Store3/ReturnOperations';

import './App.css';

function App() {
  return (
    <Router>
      <div className="flex">
        <Sidebar />
        <div className="flex-1 ml-64">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            
            {/* Store1 Routes */}
            <Route path="/store1/stock" element={<Store1StockOperations />} />
            <Route path="/store1/sales" element={<Store1SalesOperations />} />
            <Route path="/store1/returns" element={<Store1ReturnOperations />} />
            
            {/* Store2 Routes */}
            <Route path="/store2/stock" element={<Store2StockOperations />} />
            <Route path="/store2/sales" element={<Store2SalesOperations />} />
            <Route path="/store2/returns" element={<Store2ReturnOperations />} />
            
            {/* Store3 Routes */}
            <Route path="/store3/stock" element={<Store3StockOperations />} />
            <Route path="/store3/sales" element={<Store3SalesOperations />} />
            <Route path="/store3/returns" element={<Store3ReturnOperations />} />
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
